	@Test
	void committedPendingParentCannotServeReleasedPredecessorChildren(@TempDir File dataDir) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		try (HookValueStore store = new HookValueStore(dataDir)) {
			TripleTerm expected = vf.createTripleTerm(vf.createIRI("urn:predecessor:subject"),
					vf.createIRI("urn:predecessor:predicate"), vf.createBNode("predecessor-child"));
			store.startTransaction(true);
			store.storeValue(expected.getSubject());
			store.storeValue(expected.getPredicate());
			store.storeValue(expected.getObject());
			store.commit();
			long parentId;
			long childEpoch;
			try (ValueResolutionScope creator = store.openValueResolutionScope();
					SailClosable activation = creator.activate()) {
				store.startTransaction(true);
				parentId = store.storeValue(expected);
				LmdbValue parent = store.getLazyValue(parentId);
				parent.init();
				LmdbValue child = (LmdbValue) ((TripleTerm) parent).getObject();
				assertInstanceOf(ValueStoreRevision.Lazy.class, child.getValueStoreRevision());
				childEpoch = child.getValueStoreRevision().getRevisionId();
				assertTrue(childEpoch != parent.getValueStoreRevision().getRevisionId(),
						"the pending parent must actually contain a predecessor child capability");
				store.commit();
			}
			assertTrue(store.unusedRevisionIds.contains(childEpoch),
					"the unexported predecessor has no remaining logical owner after commit");
			try (ValueResolutionScope next = store.openValueResolutionScope();
					SailClosable activation = next.activate()) {
				assertEquals(expected, store.getLazyValue(parentId),
						"a later scope must not consume a cached parent with already released child capabilities");
			}
		}
	}

	@Test
	void repeatedNakedCanonicalLookupRegistersOneSurvivingScalar(@TempDir File dataDir) throws Exception {
		long id;
		try (HookValueStore seed = new HookValueStore(dataDir)) {
			id = commitValue(seed, SimpleValueFactory.getInstance().createBNode("canonical-cold-scalar"));
		}
		HookValueStore store = new HookValueStore(dataDir);
		LmdbValue held = store.getLazyValue(id);
		for (int i = 0; i < 1000; i++) {
			assertSame(held, store.getLazyValue(id));
		}
		assertEquals(1, shutdownTrackedValues(store), "weak registration is by referent identity");
		store.close();
		assertEquals("canonical-cold-scalar", held.stringValue());
	}

	@Test
	void scopeAdmissionFollowsWriterPublicationLockOrder(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ExecutorService workers = Executors.newFixedThreadPool(2)) {
			CountDownLatch insideCommit = new CountDownLatch(1);
			CountDownLatch releaseCommit = new CountDownLatch(1);
			store.beforeCommit = () -> {
				insideCommit.countDown();
				try {
					await(releaseCommit);
				} catch (IOException failure) {
					throw new SailException(failure);
				}
			};
			Future<?> writer = workers.submit(() -> {
				commitValue(store, SimpleValueFactory.getInstance().createBNode("admission-order"));
				return null;
			});
			assertTrue(insideCommit.await(10, TimeUnit.SECONDS));
			AtomicReference<Thread> openingThread = new AtomicReference<>();
			Future<?> opener = workers.submit(() -> {
				openingThread.set(Thread.currentThread());
				try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(5000);
						QueryExecutionDeadline.Scope entered = deadline.enter();
						ValueResolutionScope scope = store.openValueResolutionScope()) {
					assertTrue(scope.isOpen());
				}
			});
			Field field = ValueStore.class.getDeclaredField("associationGate");
			field.setAccessible(true);
			ReentrantLock gate = (ReentrantLock) field.get(store);
			long limit = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
			try {
				while ((openingThread.get() == null || !gate.hasQueuedThread(openingThread.get()))
						&& System.nanoTime() < limit) {
					Thread.onSpinWait();
				}
				assertTrue(openingThread.get() != null && gate.hasQueuedThread(openingThread.get()),
						"scope admission must be waiting at the writer's association gate");
			} finally {
				releaseCommit.countDown();
			}
			writer.get(10, TimeUnit.SECONDS);
			opener.get(10, TimeUnit.SECONDS);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void foregroundResultRowsReuseTheirOwnersDictionaryReader(boolean explicit, @TempDir File dataDir)
			throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		ObservedStore store = new ObservedStore(dataDir);
		store.init();
		try (SailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			for (int i = 0; i < 32; i++) {
				writer.addStatement(vf.createIRI("urn:rows:subject:" + i), vf.createIRI("urn:rows:predicate"),
						vf.createLiteral("row-dictionary-" + i, vf.createIRI("urn:rows:datatype")));
			}
			writer.commit();
		} finally {
			store.shutDown();
		}
		store.init();
		try (SailConnection reader = store.getConnection()) {
			if (explicit) {
				reader.begin(IsolationLevels.SNAPSHOT);
			}
			int count = 0;
			try (CloseableIteration<? extends BindingSet> rows = reader.evaluate(QueryParserUtil.parseTupleQuery(
					QueryLanguage.SPARQL,
					"SELECT ?s (STR(?o) AS ?label) WHERE { ?s <urn:rows:predicate> ?o }", null).getTupleExpr(),
					null, EmptyBindingSet.getInstance(), false)) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					assertTrue(row.getValue("label").stringValue().startsWith("row-dictionary-"));
					count++;
				}
				assertTrue(store.values.retainedDecodes.get() > 1,
						"the cold streaming fixture must actually use retained dictionary decode");
				assertEquals(1, store.values.retainedAdmissions.get(),
						"foreground hasNext/next exposures must reuse their owner's reader across rows");
			}
			assertEquals(32, count);
			if (explicit) {
				reader.rollback();
			}
			for (TxnManager.Txn nativeReader : store.values.retainedReaders) {
				assertTrue(nativeReader.isIdle() || nativeReader.isClosed(),
						"completion must return the foreground lease to its native pool or close it");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void nakedCompositeEscapeOwnsLazyChildrenFromAnOpenCreator(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope()) {
			SimpleValueFactory vf = SimpleValueFactory.getInstance();
			long id = commitValue(store, vf.createTripleTerm(vf.createIRI("urn:cold:subject"),
					vf.createIRI("urn:cold:predicate"), vf.createTripleTerm(vf.createBNode("cold-child"),
							vf.createIRI("urn:cold:inner"),
							vf.createLiteral("cold-label", vf.createIRI("urn:cold:type")))));
			LmdbValue parent;
			try (SailClosable activation = scope.activate()) {
				parent = store.getLazyValue(id);
			}
			assertSame(parent, store.getLazyValue(id));
			assertInstanceOf(ValueStoreRevision.Lazy.class, parent.getValueStoreRevision(),
					"the low-level lazy API must preserve the canonical parent's deferred payload");
			TripleTerm child = (TripleTerm) ((TripleTerm) parent).getObject();
			assertInstanceOf(ValueStoreRevision.Lazy.class, ((LmdbValue) child).getValueStoreRevision(),
					"cold ownership must preserve deferred children while protecting their shutdown lifetime");
			scope.close();
			store.close();
			assertEquals("cold-label", child.getObject().stringValue());
		}
	}

	@Test
	void nakedParentExportsChildrenInsideAnotherAmbientScope(@TempDir File directory) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		for (boolean closeCreator : new boolean[] { false, true }) {
			File dataDir = new File(directory, Boolean.toString(closeCreator));
			assertTrue(dataDir.mkdir());
			HookValueStore store = new HookValueStore(dataDir);
			try (ValueResolutionScope creator = store.openValueResolutionScope();
					ValueResolutionScope worker = store.openValueResolutionScope()) {
				long id = commitValue(store, vf.createTripleTerm(vf.createIRI("urn:ambient:subject"),
						vf.createIRI("urn:ambient:predicate"), vf.createTripleTerm(vf.createBNode("ambient-child"),
								vf.createIRI("urn:ambient:inner"),
								vf.createLiteral("ambient-label", vf.createIRI("urn:ambient:type")))));
				LmdbValue parent;
				try (SailClosable activation = creator.activate()) {
					parent = store.getLazyValue(id);
				}
				assertSame(parent, store.getLazyValue(id));
				assertInstanceOf(ValueStoreRevision.Lazy.class, parent.getValueStoreRevision());
				if (closeCreator) {
					creator.close();
				}
				TripleTerm child;
				try (SailClosable activation = worker.activate()) {
					parent.init();
					child = (TripleTerm) ((TripleTerm) parent).getObject();
					assertInstanceOf(ValueStoreRevision.Lazy.class, ((LmdbValue) child).getValueStoreRevision());
					assertTrue(shutdownTrackedValues(store) >= 2,
							"a returned child must have independent cold ownership before the parent can be dropped");
				}
				parent = null;
				creator.close();
				worker.close();
				store.close();
				assertEquals("ambient-label", child.getObject().stringValue());
				assertEquals("ambient-label", child.getObject().stringValue(),
						"post-store-close reference getters must not attempt fresh epoch admission");
			} finally {
				store.close();
			}
		}
	}

	@Test
	void nakedReadyParentPromotesAnOlderLazyChild(@TempDir File dataDir) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope creator = store.openValueResolutionScope()) {
			long childId = commitValue(store, vf.createBNode("older-cold-child"));
			LmdbValue child;
			try (SailClosable activation = creator.activate()) {
				child = store.getLazyValue(childId);
			}
			long olderEpoch = child.getValueStoreRevision().getRevisionId();
			store.startTransaction(true);
			store.rollback();
			long parentId = commitValue(store, vf.createTripleTerm(vf.createIRI("urn:older:subject"),
					vf.createIRI("urn:older:predicate"), vf.createBNode("older-cold-child")));
			LmdbTripleTerm ready = new LmdbTripleTerm(store.getRevision(), vf.createIRI("urn:older:subject"),
					vf.createIRI("urn:older:predicate"), child, parentId);
			store.cacheValue(parentId, ready);
			assertSame(ready, store.getLazyValue(parentId));
			assertInstanceOf(ValueStoreRevision.Lazy.class, child.getValueStoreRevision());
			creator.close();
			assertFalse(store.unusedRevisionIds.contains(olderEpoch),
					"cold composite exposure must pin the child's actual older capability");
			store.close();
			assertEquals("older-cold-child", ready.getObject().stringValue());
			assertEquals("older-cold-child", child.stringValue());
		}
	}

	@Test
	void coldLookupOverlapsAnAlreadyRunningUnmarkedDecode(@TempDir File dataDir) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope();
				ExecutorService executor = Executors.newFixedThreadPool(2)) {
			long id = commitValue(store, vf.createTripleTerm(vf.createIRI("urn:overlap:subject"),
					vf.createIRI("urn:overlap:predicate"), vf.createBNode("overlap-cold-child")));
			LmdbValue parent;
			try (SailClosable activation = scope.activate()) {
				parent = store.getLazyValue(id);
			}
			CountDownLatch decoding = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			store.nativeHook = lookupId -> {
				if (lookupId == id) {
					decoding.countDown();
					await(release);
				}
			};
			Future<?> decode = executor.submit(() -> {
				try (SailClosable activation = scope.activate()) {
					parent.init();
				}
			});
			try {
				assertTrue(decoding.await(10, TimeUnit.SECONDS));
				Future<LmdbValue> escaped = executor.submit(() -> store.getLazyValue(id));
				assertSame(parent, escaped.get(10, TimeUnit.SECONDS),
						"cold lookup must preserve lazy lookup without waiting for an in-flight native decode");
			} finally {
				release.countDown();
			}
			decode.get(10, TimeUnit.SECONDS);
			assertTrue(shutdownTrackedValues(store) >= 2,
					"late cold marking must protect children published by the already running decoder");
			scope.close();
			store.close();
			assertEquals("overlap-cold-child", ((TripleTerm) parent).getObject().stringValue());
		}
	}

	@Test
	void expiredDeadlineRejectsScopeAdmissionWithoutRetainingAnEpoch(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1)) {
			CountDownLatch expired = new CountDownLatch(1);
			try (QueryExecutionDeadline.Registration registration = deadline.onExpiration(expired::countDown)) {
				assertTrue(expired.await(10, TimeUnit.SECONDS));
			}
			try (QueryExecutionDeadline.Scope activation = deadline.enter()) {
				assertThrows(QueryInterruptedException.class, () -> {
					try (ValueResolutionScope ignored = store.openValueResolutionScope()) {
						// Admission must check an already expired deadline even when the gate is uncontended.
					}
				});
			}
			try (ValueResolutionScope scope = store.openValueResolutionScope()) {
				assertTrue(scope.isOpen(), "failed deadline admission must leave later admission usable");
			}
		}
	}

	@Test
	void earlyReservationProtectsManyRetiredCohortsUntilItsRelease(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope()) {
			List<Long> revisions = new ArrayList<>();
			for (int i = 0; i < 64; i++) {
				long id = commitValue(store, SimpleValueFactory.getInstance().createBNode("retired-cohort-" + i));
				try (SailClosable activation = scope.activate()) {
					revisions.add(store.getLazyValue(id).getValueStoreRevision().getRevisionId());
				}
				store.startTransaction(true);
				store.gcIds(Set.of(id), new HashSet<>());
				store.commit();
			}
			for (long revision : revisions) {
				assertFalse(store.unusedRevisionIds.contains(revision));
			}
			scope.close();
			for (long revision : revisions) {
				assertTrue(store.unusedRevisionIds.contains(revision));
			}
		}
	}

	@Test
	void nakedInitializedCompositeCacheHitsPreserveLazyDescendants(@TempDir File directory) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		for (boolean lazyLookup : new boolean[] { true, false }) {
			File dataDir = new File(directory, lazyLookup ? "lazy" : "value");
			assertTrue(dataDir.mkdir());
			HookValueStore store = new HookValueStore(dataDir);
			TripleTerm expected = vf.createTripleTerm(vf.createIRI("urn:composite:subject"),
					vf.createIRI("urn:composite:predicate"),
					vf.createTripleTerm(vf.createBNode("composite-child"), vf.createIRI("urn:composite:inner"),
							vf.createLiteral("composite-label", vf.createIRI("urn:composite:datatype"))));
			long id = commitValue(store, expected);
			LmdbValue parent;
			try (ValueResolutionScope scope = store.openValueResolutionScope();
					SailClosable activation = scope.activate()) {
				parent = store.getLazyValue(id);
				parent.init();
				assertInstanceOf(ValueStoreRevision.Default.class, parent.getValueStoreRevision());
				assertInstanceOf(ValueStoreRevision.Lazy.class,
						((LmdbValue) ((TripleTerm) parent).getObject()).getValueStoreRevision());
			}
			assertSame(parent, lazyLookup ? store.getLazyValue(id) : store.getValue(id),
					"cold escape must preserve the already initialized canonical composite");
			store.close();
			assertEquals(expected, parent,
					"all descendants of a naked cached composite must remain usable after store shutdown");
		}
	}

	@Test
	void encounteringAnOlderCapabilityExtendsTheScopeHorizon(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope older = store.openValueResolutionScope()) {
			long id = commitValue(store, SimpleValueFactory.getInstance().createBNode("older-capability"));
			ValueStoreRevision.Lazy capability;
			try (SailClosable activation = older.activate()) {
				capability = ((ValueStoreRevision.Lazy) store.getLazyValue(id).getValueStoreRevision()).epoch();
			}
			store.startTransaction(true);
			store.gcIds(Set.of(id), new HashSet<>());
			store.commit();
			try (ValueResolutionScope newer = store.openValueResolutionScope()) {
				LmdbValue held;
				try (SailClosable activation = newer.activate()) {
					// Stable paired views use this same captured-revision lookup when their dictionary epoch
					// predates the logical scope that is now consuming them.
					held = store.getLazyValue(id, capability);
				}
				older.close();
				assertFalse(store.unusedRevisionIds.contains(capability.getRevisionId()),
						"the new scope must retain an earlier encountered capability after its original owner closes");
				assertEquals("older-capability", ((BNode) held).getID());
			}
			assertTrue(store.unusedRevisionIds.contains(capability.getRevisionId()));
		}
	}

	@Test
	void pressureFallbackPinsItsEpochThroughTheBorrowedDecode(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ExecutorService workers = Executors.newFixedThreadPool(2)) {
			long id = commitValue(store, SimpleValueFactory.getInstance().createBNode("borrowed-epoch"));
			ValueResolutionScope scope = store.openValueResolutionScope();
			LmdbValue held;
			try (SailClosable activation = scope.activate()) {
				held = store.getLazyValue(id);
			}
			long epoch = held.getValueStoreRevision().getRevisionId();
			List<TxnManager.Txn> ordinary = new ArrayList<>();
			for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
				ordinary.add(store.getTxnManager().createReadTxnUntracked());
			}
			CountDownLatch insideNative = new CountDownLatch(1);
			CountDownLatch releaseNative = new CountDownLatch(1);
			CountDownLatch writerPublished = new CountDownLatch(1);
			store.hook = ignored -> {
				insideNative.countDown();
				await(releaseNative);
			};
			Future<?> getter = workers.submit(held::init);
			Future<?> writer = null;
			try {
				assertTrue(insideNative.await(10, TimeUnit.SECONDS), "the reserved short fallback must enter decode");
				scope.close();
				store.afterTransaction = writerPublished::countDown;
				writer = workers.submit(() -> {
					store.startTransaction(true);
					store.gcIds(Set.of(id), new HashSet<>());
					store.commit();
					return null;
				});
				assertTrue(writerPublished.await(10, TimeUnit.SECONDS),
						"writer publication must finish before its native-reader reset waits on decode");
				assertFalse(store.unusedRevisionIds.contains(epoch),
						"the borrowed callback must keep its epoch pinned after native start and creator close");
			} finally {
				releaseNative.countDown();
				ordinary.forEach(TxnManager.Txn::close);
				scope.close();
			}
			getter.get(10, TimeUnit.SECONDS);
			writer.get(10, TimeUnit.SECONDS);
			assertEquals("borrowed-epoch", held.stringValue());
			assertTrue(store.unusedRevisionIds.contains(epoch));
		}
	}

	@Test
	void admissionIntentCoversTheLastScanBeforeSemaphoreQueue(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope();
				ExecutorService workers = Executors.newVirtualThreadPerTaskExecutor()) {
			List<LmdbValue> values = new ArrayList<>();
			store.startTransaction(true);
			List<Long> ids = new ArrayList<>();
			for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
				ids.add(store.storeValue(SimpleValueFactory.getInstance().createBNode("intent-park-" + i)));
			}
			store.commit();
			try (SailClosable activation = scope.activate()) {
				for (long id : ids) {
					values.add(store.getLazyValue(id));
				}
			}
			CountDownLatch insideNative = new CountDownLatch(values.size());
			CountDownLatch releaseNative = new CountDownLatch(1);
			CountDownLatch beforeQueue = new CountDownLatch(1);
			CountDownLatch releaseAdmission = new CountDownLatch(1);
			store.hook = ignored -> {
				insideNative.countDown();
				await(releaseNative);
			};
			store.getTxnManager().beforeBlockingReaderAdmissionForTest = () -> {
				beforeQueue.countDown();
				try {
					await(releaseAdmission);
				} catch (IOException failure) {
					throw new SailException(failure);
				}
			};
			List<Future<?>> getters = new ArrayList<>();
			for (LmdbValue value : values) {
				getters.add(workers.submit(value::init));
			}
			assertTrue(insideNative.await(10, TimeUnit.SECONDS));
			Future<?> admission = workers.submit(() -> {
				try (ValueStore.ReadSnapshotReservation reservation = store.reserveReadSnapshot()) {
					return null;
				}
			});
			try {
				assertTrue(beforeQueue.await(10, TimeUnit.SECONDS));
				releaseNative.countDown();
				for (Future<?> getter : getters) {
					getter.get(10, TimeUnit.SECONDS);
				}
				releaseAdmission.countDown();
				admission.get(10, TimeUnit.SECONDS);
			} finally {
				releaseNative.countDown();
				releaseAdmission.countDown();
				admission.cancel(true);
				store.getTxnManager().beforeBlockingReaderAdmissionForTest = null;
			}
		}
	}

