	@Test
	void queuedOrdinaryAdmissionReceivesAReaderWhenBusyLeasesPark(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope();
				ExecutorService workers = Executors.newVirtualThreadPerTaskExecutor()) {
			int capacity = ordinaryCapacity(store.getTxnManager());
			List<LmdbValue> values = new ArrayList<>();
			store.startTransaction(true);
			List<Long> ids = new ArrayList<>();
			for (int i = 0; i < capacity; i++) {
				ids.add(store.storeValue(SimpleValueFactory.getInstance().createBNode("busy-park-" + i)));
			}
			store.commit();
			try (SailClosable activation = scope.activate()) {
				for (long id : ids) {
					values.add(store.getLazyValue(id));
				}
			}
			CountDownLatch insideNative = new CountDownLatch(capacity);
			CountDownLatch releaseNative = new CountDownLatch(1);
			store.hook = id -> {
				insideNative.countDown();
				await(releaseNative);
			};
			List<Future<?>> getters = new ArrayList<>();
			for (LmdbValue value : values) {
				getters.add(workers.submit(value::init));
			}
			Future<?> reservation = null;
			try {
				assertTrue(insideNative.await(10, TimeUnit.SECONDS));
				assertEquals(0, ordinaryCapacity(store.getTxnManager()));
				reservation = workers.submit(() -> {
					try (ValueStore.ReadSnapshotReservation acquired = store.reserveReadSnapshot()) {
						return null;
					}
				});
				Semaphore slots = ordinarySlots(store.getTxnManager());
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				while (!slots.hasQueuedThreads() && System.nanoTime() < deadline) {
					Thread.onSpinWait();
				}
				assertTrue(slots.hasQueuedThreads(), "the ordinary caller must queue while every lease is busy");
			} finally {
				releaseNative.countDown();
			}
			for (Future<?> getter : getters) {
				getter.get(10, TimeUnit.SECONDS);
			}
			try {
				reservation.get(10, TimeUnit.SECONDS);
			} finally {
				reservation.cancel(true);
			}
		}
	}

	@Test
	void standaloneReadsOwnAScopeUntilResultClose(@TempDir File dataDir) throws Exception {
		ObservedStore store = seedNestedStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection reader = repository.getConnection()) {
			AtomicReference<ValueResolutionScope> observed = new AtomicReference<>();
			store.values.hook = id -> {
				ValueResolutionScope current = ValueResolutionScope.current(store.values);
				assertTrue(current != null && current.isOpen(),
						"a standalone read must resolve its dictionary values inside an owned scope");
				observed.compareAndSet(null, current);
				assertSame(observed.get(), current);
			};
			try (RepositoryResult<Statement> statements = reader.getStatements(null, null, null, false)) {
				assertTrue(statements.hasNext());
				statements.next();
				assertTrue(observed.get().isOpen(),
						"without speculative exhaustion the result keeps its owner until close or the next hasNext");
			}
			assertFalse(observed.get().isOpen(), "closing a standalone result must release its owned scope");
			assertNull(ValueResolutionScope.current(store.values));
		} finally {
			store.values.hook = id -> {
			};
			repository.shutDown();
		}
	}

