	@Test
	void publicResultsRecursivelyInitializeNestedValuesBeforeEscape(@TempDir File dataDir) throws Exception {
		ObservedStore store = seedNestedStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		Statement escaped;
		try (RepositoryConnection reader = repository.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT);
			try (RepositoryResult<Statement> statements = reader.getStatements(null, null, null, false)) {
				assertTrue(statements.hasNext());
				escaped = statements.next();
				assertRecursivelyReady(escaped.getSubject());
				assertRecursivelyReady(escaped.getPredicate());
				assertRecursivelyReady(escaped.getObject());
			}
			reader.rollback();
		} finally {
			repository.shutDown();
		}
		assertEquals("nested-egress-label", ((Literal) ((TripleTerm) ((TripleTerm) escaped.getObject()).getObject())
				.getObject()).getLabel());
	}

	private static ObservedStore seedNestedStore(File directory) {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		ObservedStore store = new ObservedStore(directory);
		store.init();
		try (SailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			TripleTerm nested = vf.createTripleTerm(vf.createBNode("nested-egress-subject"),
					vf.createIRI("urn:nested-egress:inner-predicate"),
					vf.createLiteral("nested-egress-label", vf.createIRI("urn:nested-egress:datatype")));
			writer.addStatement(vf.createIRI("urn:nested-egress:subject"), vf.createIRI("urn:nested-egress:predicate"),
					vf.createTripleTerm(vf.createIRI("urn:nested-egress:quoted-subject"),
							vf.createIRI("urn:nested-egress:quoted-predicate"), nested));
			writer.commit();
		} finally {
			store.shutDown();
		}
		return store;
	}

	private static void assertRecursivelyReady(Value value) {
		if (value instanceof LmdbValue lmdb) {
			assertInstanceOf(ValueStoreRevision.Default.class, lmdb.getValueStoreRevision(),
					"every reachable public value must be initialized before it escapes");
		}
		if (value instanceof TripleTerm triple) {
			assertRecursivelyReady(triple.getSubject());
			assertRecursivelyReady(triple.getPredicate());
			assertRecursivelyReady(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertRecursivelyReady(literal.getDatatype());
		}
	}

	private static int shutdownTrackedValues(ValueStore store) throws ReflectiveOperationException {
		// Read-only ownership diagnostics, just like the ordinary native admission observation below.
		Field registry = ValueStore.class.getDeclaredField("sharedLazyValues");
		registry.setAccessible(true);
		Object tracker = registry.get(store);
		Field values = tracker.getClass().getDeclaredField("values");
		values.setAccessible(true);
		return ((Set<?>) values.get(tracker)).size();
	}

	@Test
	void foregroundGettersRetainOneReaderUntilTransactionEnds(@TempDir File dataDir) throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		ObservedStore store = new ObservedStore(dataDir);
		store.init();
		try (SailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.addStatement(vf.createIRI("urn:scope:first"), vf.createIRI("urn:scope:predicate"),
					vf.createTripleTerm(vf.createIRI("urn:scope:inner"), vf.createIRI("urn:scope:inner-predicate"),
							vf.createBNode("first-dictionary-value")));
			writer.addStatement(vf.createIRI("urn:scope:second"), vf.createIRI("urn:scope:predicate"),
					vf.createTripleTerm(vf.createIRI("urn:scope:inner"), vf.createIRI("urn:scope:inner-predicate"),
							vf.createBNode("second-dictionary-value")));
			writer.commit();
		} finally {
			store.shutDown();
		}

		store.init();
		try (SailConnection reader = store.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT);
			List<BNode> deferred = new ArrayList<>();
			// Public output is now recursively eager. Exercise the same transaction-owned foreground
			// optimization on its cold internal models, before crossing any outward boundary.
			try (SailClosable activation = transactionScope(reader).activate()) {
				for (String label : List.of("first-dictionary-value", "second-dictionary-value")) {
					long id = store.values.getId(vf.createBNode(label));
					BNode value = (BNode) store.values.getLazyValue(id);
					assertInstanceOf(ValueStoreRevision.Lazy.class, ((LmdbValue) value).getValueStoreRevision());
					deferred.add(value);
				}
			}
			assertEquals(2, deferred.size());
			int beforeGetter = ordinaryCapacity(store.values.getTxnManager());
			deferred.get(0).getID();
			assertEquals(beforeGetter - 1, ordinaryCapacity(store.values.getTxnManager()),
					"the transaction must retain its foreground dictionary reader after a cold getter");
			deferred.get(1).getID();
			assertEquals(beforeGetter - 1, ordinaryCapacity(store.values.getTxnManager()),
					"successive dictionary getters must reuse the same ordinary reader");
			reader.rollback();
			assertEquals(beforeGetter, ordinaryCapacity(store.values.getTxnManager()),
					"transaction completion must return the resolution reader, preserving existing snapshot ownership");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void workersDecodeConcurrentlyAndReleaseTheirPrivateReaders(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ValueResolutionScope scope = store.openValueResolutionScope();
				ExecutorService workers = Executors.newFixedThreadPool(2)) {
			long first = commitValue(store, SimpleValueFactory.getInstance().createBNode("parallel-first"));
			long second = commitValue(store, SimpleValueFactory.getInstance().createBNode("parallel-second"));
			CountDownLatch insideNative = new CountDownLatch(2);
			CountDownLatch releaseNative = new CountDownLatch(1);
			store.hook = id -> {
				if (id == first || id == second) {
					insideNative.countDown();
					await(releaseNative);
				}
			};
			int capacity = ordinaryCapacity(store.getTxnManager());
			List<Future<?>> results = new ArrayList<>();
			for (long id : new long[] { first, second }) {
				results.add(workers.submit(() -> {
					try (SailClosable activation = scope.activate()) {
						LmdbValue value = store.getLazyValue(id);
						value.init();
						try (SailClosable nested = scope.activate()) {
							assertEquals(id, value.getInternalID());
						}
					}
					return null;
				}));
			}
			try {
				assertTrue(insideNative.await(10, TimeUnit.SECONDS),
						"distinct-value native decodes must overlap without a shared reader monitor");
				assertEquals(capacity - 2, ordinaryCapacity(store.getTxnManager()));
			} finally {
				releaseNative.countDown();
			}
			for (Future<?> result : results) {
				result.get(10, TimeUnit.SECONDS);
			}
			assertEquals(capacity, ordinaryCapacity(store.getTxnManager()),
					"each completed worker activation must return its own native reader");
		}
	}

