	@Test
	void closeDrainsAnAdmittedGetterWhileLaterGettersFallBack(@TempDir File dataDir) throws Exception {
		try (HookValueStore store = new HookValueStore(dataDir);
				ExecutorService workers = Executors.newFixedThreadPool(2)) {
			long first = commitValue(store, SimpleValueFactory.getInstance().createBNode("closing-admitted"));
			long second = commitValue(store, SimpleValueFactory.getInstance().createBNode("closing-escaped"));
			ValueResolutionScope scope = store.openValueResolutionScope();
			LmdbValue admitted;
			LmdbValue escaped;
			try (SailClosable activation = scope.activate()) {
				admitted = store.getLazyValue(first);
				escaped = store.getLazyValue(second);
			}
			int capacity = ordinaryCapacity(store.getTxnManager());
			CountDownLatch insideNative = new CountDownLatch(1);
			CountDownLatch releaseNative = new CountDownLatch(1);
			store.hook = id -> {
				if (id == first) {
					insideNative.countDown();
					await(releaseNative);
				}
			};
			Future<?> getter = workers.submit(admitted::init);
			assertTrue(insideNative.await(10, TimeUnit.SECONDS));
			Future<?> close = workers.submit(scope::close);
			try {
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				while (scope.isOpen() && System.nanoTime() < deadline) {
					Thread.onSpinWait();
				}
				assertFalse(scope.isOpen(), "close must atomically seal admission before draining the native getter");
				assertFalse(close.isDone(), "close must wait for the previously admitted native access");
				assertEquals("closing-escaped", ((BNode) escaped).getID());
				assertEquals(capacity - 1, ordinaryCapacity(store.getTxnManager()),
						"the later getter must use short lazy fallback without retaining a second reader");
			} finally {
				releaseNative.countDown();
			}
			getter.get(10, TimeUnit.SECONDS);
			close.get(10, TimeUnit.SECONDS);
			assertEquals(capacity, ordinaryCapacity(store.getTxnManager()));
		}
	}

